package com.example.platform.studio.storyboard;
import com.example.platform.shared.digest.ContentDigest;import com.example.platform.studio.digest.StudioDigest;import com.example.platform.studio.identity.*;import com.example.platform.studio.reference.StudioVersionPin;import com.example.platform.studio.scope.StudioScope;import com.example.platform.studio.serialization.CanonicalJson;import com.example.platform.studio.shotplan.ShotPlanVersion;import java.util.*;
public final class StoryboardVersion{public static final int SCHEMA_VERSION=1;private final StoryboardId id;private final StoryboardVersionId versionId;private final StudioScope scope;private final StoryboardVersionId parentVersionId;private final StudioVersionPin<ShotPlanId,ShotPlanVersionId>shotPlanPin;private final List<StoryboardPanel>panels;private final byte[]canonicalBytes;private final ContentDigest semanticDigest;
private StoryboardVersion(StoryboardId id,StoryboardVersionId versionId,StudioScope scope,StoryboardVersionId parentVersionId,ShotPlanVersion plan,List<StoryboardPanel>panels){if(id==null||versionId==null||scope==null||plan==null||panels==null||panels.isEmpty())throw new IllegalArgumentException("storyboard fields required");if(versionId.equals(parentVersionId))throw new IllegalArgumentException("version cannot parent itself");if(!scope.equals(plan.scope()))throw new IllegalArgumentException("shot plan scope mismatch");var seen=new HashSet<StoryboardPanelId>();for(var p:panels){if(p==null||!seen.add(p.id()))throw new IllegalArgumentException("duplicate panel identity");if(!p.shotPin().scope().equals(scope)||!plan.shotPins().contains(p.shotPin()))throw new IllegalArgumentException("panel shot pin mismatch");if(p.cameraPlanPin()!=null&&!p.cameraPlanPin().scope().equals(scope))throw new IllegalArgumentException("panel camera scope mismatch");}this.id=id;this.versionId=versionId;this.scope=scope;this.parentVersionId=parentVersionId;this.shotPlanPin=plan.pin();this.panels=List.copyOf(panels);this.canonicalBytes=serialize();this.semanticDigest=StudioDigest.sha256(canonicalBytes);}
public static StoryboardVersion create(StoryboardId id,StoryboardVersionId versionId,StudioScope scope,StoryboardVersionId parentVersionId,ShotPlanVersion plan,List<StoryboardPanel>panels){return new StoryboardVersion(id,versionId,scope,parentVersionId,plan,panels);}
private byte[]serialize(){Map<String,String>m=new LinkedHashMap<>();m.put("aggregateId",CanonicalJson.quote(id.value()));m.put("panels",CanonicalJson.array(panels.stream().map(StoryboardPanel::canonicalJson).toList()));if(parentVersionId!=null)m.put("parentVersionId",CanonicalJson.quote(parentVersionId.value()));m.put("projectId",CanonicalJson.quote(scope.projectId().value()));m.put("schemaVersion","1");m.put("shotPlanPin",shotPlanPin.canonicalJson());m.put("tenantId",CanonicalJson.quote(scope.tenantId().value()));m.put("type",CanonicalJson.quote("STORYBOARD_VERSION"));m.put("versionId",CanonicalJson.quote(versionId.value()));return CanonicalJson.utf8(CanonicalJson.object(m));}
public StudioVersionPin<StoryboardId,StoryboardVersionId>pin(){return new StudioVersionPin<>(StudioVersionPin.AggregateKind.STORYBOARD,id,versionId,scope,1,semanticDigest);}public StoryboardId id(){return id;}public StoryboardVersionId versionId(){return versionId;}public StudioScope scope(){return scope;}public StoryboardVersionId parentVersionId(){return parentVersionId;}public List<StoryboardPanel>panels(){return panels;}public byte[]canonicalBytes(){return canonicalBytes.clone();}public ContentDigest semanticDigest(){return semanticDigest;}}
